        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = window.mySimulation.t(round.briefingKey);
            }

            var sel = document.getElementById('strategySelect');
            if (sel) {
                sel.innerHTML = '';
                for (var i = 0; i < round.optionKeys.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = i + 1;
                    opt.textContent = window.mySimulation.t(round.optionKeys[i]);
                    sel.appendChild(opt);
                }
            }

            var fbPanel = document.getElementById('feedbackPanel');
            if (fbPanel && state.currentPeriod === 1) {
                fbPanel.style.display = 'none';
            }
        }
    }

